.site-footer {
  background-color: var(--color-primary-dark);
  color: #ffffff;
  padding: var(--spacing-xl) var(--spacing-md);
  margin-top: var(--spacing-xl);
  text-align: center;
}

.site-footer a {
  color: #ffffff;
  text-decoration: underline;
}

.site-footer a:hover, .site-footer a:focus {
  color: var(--color-accent);
}

.site-footer p {
  margin-bottom: var(--spacing-sm);
  color: #ffffff;
}

button, .button {
  display: inline-block;
  min-height: 44px;
  padding: var(--spacing-sm) var(--spacing-lg);
  background-color: var(--color-primary-dark);
  color: #ffffff;
  border: 2px solid var(--color-primary-dark);
  font-family: var(--font-sans);
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  border-radius: 4px;
  transition: all 0.3s ease;
  text-decoration: none;
}

button:hover, .button:hover {
  background-color: var(--color-primary);
  border-color: var(--color-primary);
}

button:focus, .button:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

button:active, .button:active {
  transform: scale(0.98);
}

button.secondary, .button.secondary {
  background-color: var(--color-accent-dark);
  border-color: var(--color-accent-dark);
}

button.secondary:hover, .button.secondary:hover {
  background-color: var(--color-accent);
  border-color: var(--color-accent);
}

form {
  max-width: 600px;
  margin: var(--spacing-lg) 0;
}

.form-group {
  margin-bottom: var(--spacing-lg);
}

label {
  display: block;
  margin-bottom: var(--spacing-xs);
  font-weight: 600;
  color: var(--color-text);
}

input, textarea, select {
  width: 100%;
  min-height: 44px;
  padding: var(--spacing-sm);
  font-family: var(--font-sans);
  font-size: 1rem;
  border: 2px solid var(--color-border);
  border-radius: 4px;
  transition: border-color 0.3s ease;
  color: var(--color-text);
}

textarea {
  min-height: 120px;
  resize: vertical;
}

input:focus, textarea:focus, select:focus {
  outline: none;
  border-color: var(--color-primary);
  box-shadow: 0 0 0 3px rgba(0, 102, 161, 0.1);
}

.grid {
  display: grid;
  gap: var(--spacing-lg);
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
}

.card {
  background-color: var(--color-bg-alt);
  border: 1px solid var(--color-border);
  border-radius: 8px;
  padding: var(--spacing-lg);
  transition: transform 0.3s ease, box-shadow 0.3s ease;
}

.card:hover {
  transform: translateY(-4px);
  box-shadow: 0 8px 16px rgba(0, 0, 0, 0.1);
}

.card h3 {
  margin-bottom: var(--spacing-md);
}

.card p {
  margin-bottom: var(--spacing-md);
}

.price {
  font-size: 1.5rem;
  font-weight: bold;
  color: var(--color-accent-dark);
  margin: var(--spacing-md) 0;
}

section {
  padding: var(--spacing-xl) 0;
}

@media (max-width: 600px) {
  .site-header .container {
    flex-direction: column;
    gap: var(--spacing-md);
    align-items: flex-start;
  }

  .site-header nav {
    width: 100%;
    flex-direction: column;
    gap: var(--spacing-sm);
  }

  .site-header nav a {
    display: block;
    padding: var(--spacing-sm) 0;
  }

  h1 {
    font-size: 2rem;
  }

  h2 {
    font-size: 1.5rem;
  }

  h3 {
    font-size: 1.25rem;
  }

  .grid {
    grid-template-columns: 1fr;
  }

  .container {
    padding: 0 var(--spacing-sm);
  }

  section {
    padding: var(--spacing-lg) 0;
  }

  button, .button, input, textarea, select {
    font-size: 16px;
  }
}

@media (min-width: 601px) {
  .site-header nav {
    gap: var(--spacing-lg);
  }

  .grid {
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  }
}

@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

pages.css:
.index-hero {
  background: linear-gradient(135deg, var(--color-primary-light) 0%, var(--color-bg) 100%);
  padding: var(--spacing-xl) 0;
  text-align: center;
}

.index-hero h1 {
  margin-bottom: var(--spacing-md);
}

.index-hero-subtitle {
  font-size: 1.25rem;
  color: var(--color-text-light);
  margin-bottom: var(--spacing-lg);
}

.index-hero-contact {
  margin-top: var(--spacing-lg);
  display: flex;
  flex-direction: column;
  gap: var(--spacing-md);
  align-items: center;
}

.index-services h2 {
  margin-bottom: var(--spacing-lg);
  text-align: center;
}

.index-benefits {
  background-color: var(--color-bg-alt);
}

.index-benefits h2 {
  text-align: center;
  margin-bottom: var(--spacing-lg);
}

.benefit-item {
  padding: var(--spacing-lg);
  border-left: 4px solid var(--color-accent-dark);
  background-color: var(--color-bg);
  border-radius: 4px;
  transition: transform 0.3s ease;
}

.benefit-item:hover {
  transform: translateX(8px);
}

.benefit-item h3 {
  margin-top: 0;
}

.index-cta {
  background-color: var(--color-primary);
  color: #ffffff;
  text-align: center;
  padding: var(--spacing-xl) 0;
}

.index-cta h2 {
  color: #ffffff;
  margin-bottom: var(--spacing-md);
}

.index-cta p {
  color: #ffffff;
}

.index-cta a {
  color: #ffffff;
}

.index-cta-info {
  margin-top: var(--spacing-lg);
  font-size: 0.95rem;
}

@media (max-width: 600px) {
  .index-hero {
    padding: var(--spacing-lg) 0;
  }

  .index-hero-subtitle {
    font-size: 1.1rem;
  }

  .index-hero-contact {
    gap: var(--spacing-md);
  }

  .benefit-item {
    padding: var(--spacing-md);
    border-left: 4px solid var(--color-accent-dark);
  }
}

@media (min-width: 601px) {
  .index-cta a.button {
    min-width: 200px;
  }
}

.services-intro {
  background-color: var(--color-primary-light);
  padding: var(--spacing-lg) 0;
}

.services-intro p {
  font-size: 1.1rem;
  color: var(--color-text);
}

.services-section {
  padding: var(--spacing-xl) 0;
}

.services-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: var(--spacing-lg);
  margin-top: var(--spacing-lg);
}

.service-card {
  background-color: var(--color-bg);
  border: 2px solid var(--color-border);
  border-radius: 8px;
  padding: var(--spacing-lg);
  display: flex;
  flex-direction: column;
  transition: all 0.3s ease;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
}

.service-card:hover {
  border-color: var(--color-primary);
  box-shadow: 0 4px 12px rgba(0, 102, 161, 0.15);
  transform: translateY(-2px);
}

.service-card h3 {
  color: var(--color-primary-dark);
  margin-bottom: var(--spacing-md);
}

.service-card p {
  flex-grow: 1;
  margin-bottom: var(--spacing-md);
  color: var(--color-text-light);
}

.service-details {
  margin: var(--spacing-md) 0;
  padding: var(--spacing-md) 0;
  border-top: 1px solid var(--color-border);
  border-bottom: 1px solid var(--color-border);
}

.service-details .price {
  display: block;
  font-size: 1.5rem;
  font-weight: bold;
  color: var(--color-accent-dark);
  margin-bottom: var(--spacing-sm);
}

.service-details .duration {
  font-size: 0.95rem;
  margin: 0;
}

.service-card .button {
  align-self: flex-start;
  margin-top: var(--spacing-md);
}

.services-info {
  background-color: var(--color-bg-alt);
  padding: var(--spacing-xl) 0;
}

.info-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: var(--spacing-lg);
  margin-top: var(--spacing-lg);
}

.info-item {
  padding: var(--spacing-lg);
  background-color: var(--color-bg);
  border-radius: 8px;
  border-left: 4px solid var(--color-accent-dark);
}

.info-item h3 {
  color: var(--color-primary-dark);
  margin-bottom: var(--spacing-md);
}

.info-item p {
  color: var(--color-text-light);
  margin: 0;
}

.services-cta {
  background: linear-gradient(135deg, var(--color-primary-dark) 0%, var(--color-primary) 100%);
  color: #ffffff;
  padding: var(--spacing-xl) 0;
  text-align: center;
}

.services-cta h2 {
  color: #ffffff;
}

.services-cta p {
  color: #ffffff;
  font-size: 1.1rem;
  margin-bottom: var(--spacing-lg);
}

@media (max-width: 600px) {
  .services-grid {
    grid-template-columns: 1fr;
    gap: var(--spacing-md);
  }

  .info-grid {
    grid-template-columns: 1fr;
    gap: var(--spacing-md);
  }

  .service-card {
    padding: var(--spacing-md);
  }

  .service-card h3 {
    font-size: 1.25rem;
  }

  .services-cta {
    padding: var(--spacing-lg) 0;
  }
}

@media (min-width: 601px) {
  .services-grid {
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  }

  .info-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

.team-intro {
  background-color: var(--color-primary-light);
}

.team-intro p {
  font-size: 1.1rem;
  text-align: center;
  max-width: 800px;
  margin-left: auto;
  margin-right: auto;
}

.team-members-section h2 {
  text-align: center;
  margin-bottom: var(--spacing-xl);
}

.team-grid {
  display: grid;
  gap: var(--spacing-lg);
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
}

.team-card {
  background-color: var(--color-bg);
  border: 2px solid var(--color-border);
  border-radius: 8px;
  overflow: hidden;
  transition: transform 0.3s ease, box-shadow 0.3s ease;
}

.team-card:hover {
  transform: translateY(-6px);
  box-shadow: 0 12px 24px rgba(0, 0, 0, 0.15);
}

.team-card img {
  width: 100%;
  height: 300px;
  object-fit: cover;
  display: block;
}

.team-card h3 {
  margin-top: var(--spacing-lg);
  margin-bottom: var(--spacing-xs);
  padding: 0 var(--spacing-lg);
}

.team-card-title {
  color: var(--color-accent-dark);
  font-weight: 600;
  font-size: 1.05rem;
  margin: 0 var(--spacing-lg) var(--spacing-md) var(--spacing-lg);
}

.team-card p:last-child {
  padding: 0 var(--spacing-lg) var(--spacing-lg) var(--spacing-lg);
  margin-bottom: 0;
}

.team-values {
  background-color: var(--color-bg-alt);
}

.team-values h2 {
  text-align: center;
  margin-bottom: var(--spacing-xl);
}

.values-grid {
  display: grid;
  gap: var(--spacing-lg);
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
}

.value-item {
  background-color: var(--color-bg);
  padding: var(--spacing-lg);
  border-radius: 8px;
  border-left: 5px solid var(--color-accent-dark);
}

.value-item h3 {
  margin-bottom: var(--spacing-md);
  color: var(--color-accent-dark);
}

.value-item p {
  margin-bottom: 0;
}

.team-cta {
  background-color: var(--color-primary-light);
  text-align: center;
}

.team-cta h2 {
  margin-bottom: var(--spacing-lg);
}

.team-cta p {
  font-size: 1.1rem;
  margin-bottom: var(--spacing-lg);
  max-width: 700px;
  margin-left: auto;
  margin-right: auto;
}

@media (max-width: 600px) {
  .team-grid {
    grid-template-columns: 1fr;
  }

  .values-grid {
    grid-template-columns: 1fr;
  }

  .team-card img {
    height: 250px;
  }

  .team-intro p,
  .team-cta p {
    font-size: 1rem;
  }
}

@media (min-width: 601px) {
  .team-grid {
    grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  }

  .values-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

.appointment-form-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--spacing-lg);
}

@media (max-width: 600px) {
  .appointment-form-row {
    grid-template-columns: 1fr;
  }
}

.appointment-required {
  font-size: 0.875rem;
  color: var(--color-text-light);
  margin-top: var(--spacing-md);
  margin-bottom: 0;
}

.contact-section {
  background-color: var(--color-primary-light);
}

.contact-info-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: var(--spacing-lg);
  margin-bottom: var(--spacing-xl);
}

.contact-card {
  background-color: var(--color-bg);
  border: 2px solid var(--color-primary);
  border-radius: 8px;
  padding: var(--spacing-lg);
  transition: transform 0.3s ease, box-shadow 0.3s ease;
}

.contact-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 8px 16px rgba(0, 102, 161, 0.15);
}

.contact-card h3 {
  margin-bottom: var(--spacing-md);
}

.contact-card p {
  margin-bottom: var(--spacing-sm);
}

.contact-highlight {
  font-size: 1.1rem;
  font-weight: 600;
  color: var(--color-primary-dark);
  margin: var(--spacing-md) 0;
}

.contact-highlight a {
  color: var(--color-primary-dark);
  text-decoration: none;
  border-bottom: 2px solid var(--color-accent);
  transition: color 0.3s ease;
}

.contact-highlight a:hover,
.contact-highlight a:focus {
  color: var(--color-accent-dark);
}

.contact-hours-note {
  font-size: 0.9rem;
  color: var(--color-text-light);
}

.contact-hours-section {
  background-color: var(--color-bg);
  border: 2px solid var(--color-primary);
  border-radius: 8px;
  padding: var(--spacing-lg);
}

.contact-hours-section h3 {
  margin-bottom: var(--spacing-md);
}

.contact-hours-list {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-sm);
  margin-bottom: var(--spacing-lg);
}

.hours-item {
  display: flex;
  justify-content: space-between;
  gap: var(--spacing-lg);
  padding-bottom: var(--spacing-sm);
  border-bottom: 1px solid var(--color-border);
}

.hours-item:last-child {
  border-bottom: none;
}

.hours-item dt {
  font-weight: 600;
  color: var(--color-text);
}

.hours-item dd {
  color: var(--color-primary-dark);
  font-weight: 500;
}

.contact-note {
  background-color: var(--color-primary-light);
  padding: var(--spacing-md);
  border-left: 4px solid var(--color-primary);
  border-radius: 4px;
  color: var(--color-text);
  margin: 0;
}

.contact-note strong {
  color: var(--color-primary-dark);
}

@media (max-width: 600px) {
  .contact-info-grid {
    grid-template-columns: 1fr;
  }

  .hours-item {
    flex-direction: column;
    gap: var(--spacing-xs);
  }
}
